package com.fitwise.app;

import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.database.Cursor;import java.util.Locale;

public class MainActivity extends Activity {
    final int BG=Color.rgb(15,15,19), PANEL=Color.rgb(29,29,36), RED=Color.rgb(255,82,82), WHITE=Color.WHITE, MUTED=Color.LTGRAY;
    FitWiseDb db; int userId=-1; String userName="Guest",email="",gender="Other",activity="Moderately Active",goal="Maintain Weight",food="No preference"; int age=20,steps=0; double height=165,weight=60,water=0,sleep=0;
    LinearLayout root,body; EditText nameField,emailField,passwordField,ageField,heightField,weightField,waterField,sleepField,stepsField;
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new FitWiseDb(this);showAuth();}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,6,0,6);return t;}
    void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,24,20,16);root.setBackgroundColor(BG);setContentView(root);root.addView(text("FITWISE  •  PERSONAL FITNESS",12,RED));root.addView(text(title,27,WHITE));ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,12,0,12);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
    EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setHintTextColor(MUTED);e.setTextColor(WHITE);e.setPadding(14,10,14,10);e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(RED));body.addView(e);return e;}
    void button(String label,Runnable r){Button b=new Button(this);b.setText(label);b.setTextColor(WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(RED));body.addView(b);b.setOnClickListener(v->r.run());}
    void card(String title,String detail){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(16,12,16,12);box.setBackgroundColor(PANEL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,7,0,7);body.addView(box,p);TextView h=text(title,18,WHITE);h.setTypeface(null,1);box.addView(h);box.addView(text(detail,14,MUTED));}
    void showAuth(){base("Welcome to FitWise");card("Your fitness, organized","Create an account or sign in to access your personal dashboard.");emailField=field("Email address");passwordField=field("Password");button("LOGIN",()->{Cursor c=db.login(val(emailField),val(passwordField));if(c.moveToFirst()){userId=c.getInt(c.getColumnIndexOrThrow("id"));userName=c.getString(c.getColumnIndexOrThrow("name"));loadUser(c);c.close();dashboard();}else{c.close();msg("Login failed","Check your email and password.");}});button("CREATE ACCOUNT",()->showRegister());}
    void showRegister(){base("Create account");nameField=field("Full name");emailField=field("Email");passwordField=field("Password (minimum 8 characters)");button("REGISTER",()->{String n=val(nameField),e=val(emailField),p=val(passwordField);if(n.isEmpty()||!e.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$")||p.length()<8){msg("Check your details","Enter a name, valid email and password with at least 8 characters.");return;}if(db.register(n,e,p)){msg("Account created","Please sign in with your new account.");showAuth();}else msg("Registration failed","This email may already be registered.");});button("BACK TO LOGIN",()->showAuth());}
    void loadUser(Cursor c){age=c.getInt(c.getColumnIndexOrThrow("age"));gender=c.getString(c.getColumnIndexOrThrow("gender"));height=c.getDouble(c.getColumnIndexOrThrow("height"));weight=c.getDouble(c.getColumnIndexOrThrow("weight"));activity=c.getString(c.getColumnIndexOrThrow("activity"));goal=c.getString(c.getColumnIndexOrThrow("goal"));food=c.getString(c.getColumnIndexOrThrow("food"));}
    double bmi(){return weight/Math.pow(height/100.0,2);} String category(){double b=bmi();return b<18.5?"Underweight":b<25?"Normal":b<30?"Overweight":"Obese";}
    double bmr(){double base=10*weight+6.25*height-5*age;return base+(gender.equals("Male")?5:gender.equals("Female")?-161:-78);} double tdee(){double m=activity.equals("Lightly Active")?1.375:activity.equals("Moderately Active")?1.55:activity.equals("Very Active")?1.725:1.2;return bmr()*m;}
    int calories(){double t=tdee();if(goal.equals("Weight Loss"))t-=300;else if(goal.equals("Weight Gain"))t+=300;else if(goal.equals("Muscle Building"))t+=200;return (int)Math.round(Math.max(bmr(),t));}
    void dashboard(){base("Hello, "+userName+" 👋");card("YOUR FITNESS SNAPSHOT",String.format(Locale.US,"BMI  %.1f  •  %s\nBMR  %.0f kcal\nTDEE  %.0f kcal\nDaily calorie estimate  %d kcal\nGoal  %s",bmi(),category(),bmr(),tdee(),calories(),goal));card("TODAY'S TRACKING",String.format(Locale.US,"Water: %.1f L   |   Sleep: %.1f hours\nSteps: %d",water,sleep,steps));button("PROFILE & FITNESS GOAL",()->profile());button("DIET PLAN",()->diet());button("WORKOUT PLAN",()->workout());button("DAILY TRACKERS",()->trackers());button("PROGRESS",()->progress());button("SMART COACH",()->coach());button("LOG OUT",()->{userId=-1;showAuth();});}
    void profile(){base("Your profile");nameField=field("Name: "+userName);ageField=field("Age: "+age);heightField=field("Height in cm: "+height);weightField=field("Weight in kg: "+weight);Spinner g=spinner(new String[]{"Other","Female","Male"},gender);Spinner a=spinner(new String[]{"Sedentary","Lightly Active","Moderately Active","Very Active"},activity);Spinner go=spinner(new String[]{"Maintain Weight","Weight Loss","Weight Gain","Muscle Building","Improve Fitness"},goal);Spinner f=spinner(new String[]{"No preference","Vegetarian","Vegan","Non-vegetarian"},food);button("SAVE PROFILE",()->{try{userName=val(nameField);age=Integer.parseInt(clean(val(ageField),"Age: ",""+age));height=Double.parseDouble(clean(val(heightField),"Height in cm: ",""+height));weight=Double.parseDouble(clean(val(weightField),"Weight in kg: ",""+weight));gender=g.getSelectedItem().toString();activity=a.getSelectedItem().toString();goal=go.getSelectedItem().toString();food=f.getSelectedItem().toString();if(age<13||height<=0||weight<=0)throw new Exception();db.saveProfile(userId,userName,age,gender,height,weight,activity,goal,food);dashboard();}catch(Exception ex){msg("Invalid profile","Please enter valid age, height and weight.");}});button("BACK",()->dashboard());}
    Spinner spinner(String[] items,String selected){Spinner s=new Spinner(this);ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items);s.setAdapter(ad);int i=java.util.Arrays.asList(items).indexOf(selected);if(i>=0)s.setSelection(i);body.addView(s);return s;}
    String clean(String s,String prefix,String fallback){return s.startsWith(prefix)?s.substring(prefix.length()).trim():fallback;} String val(EditText e){return e.getText().toString().trim();}
    void diet(){base("Personalized diet ideas");card("Daily nutrition estimate",calories()+" kcal/day estimated from your profile and selected goal. This is a general estimate, not medical advice.");card("Breakfast","Oats or whole-grain breakfast with fruit and a protein source suited to your food preference.");card("Lunch","Balanced plate with vegetables, whole grains and dal, beans, eggs or another protein source.");card("Snack","Fruit, curd or a small handful of nuts, considering allergies.");card("Dinner","A balanced meal with vegetables and a protein source. Adjust portions to your needs.");button("BACK",()->dashboard());}
    void workout(){base("Workout plan");card("Beginner-friendly routine","Warm up for 5–10 minutes. Choose activity appropriate to your fitness level.");card("Strength","Bodyweight squats, wall push-ups, glute bridges and gentle core exercises.");card("Cardio","Walking, cycling or another activity you enjoy.");card("Recovery","Include rest days and stop if you experience pain, dizziness or unusual discomfort.");button("BACK",()->dashboard());}
    void trackers(){base("Daily trackers");waterField=field("Water intake in litres (e.g. 2.0)");sleepField=field("Sleep hours (e.g. 7.5)");stepsField=field("Steps today");button("SAVE TODAY'S TRACKING",()->{try{water=Double.parseDouble(val(waterField));sleep=Double.parseDouble(val(sleepField));steps=Integer.parseInt(val(stepsField));if(water<0||sleep<0||steps<0)throw new Exception();db.saveDaily(userId,water,sleep,steps,weight);dashboard();}catch(Exception e){msg("Invalid values","Enter non-negative numbers for all trackers.");}});button("BACK",()->dashboard());}
    void progress(){base("Progress overview");card("Current measurements",String.format(Locale.US,"Weight: %.1f kg\nBMI: %.1f (%s)\nSteps today: %d\nWater today: %.1f L\nSleep: %.1f hours",weight,bmi(),category(),steps,water,sleep));card("Keep your records consistent","This starter version stores daily entries locally on this device. Historical charts and cloud synchronization are not included yet.");button("BACK",()->dashboard());}
    void coach(){base("Smart Coach");card("Your current goal",goal);card("Suggestion","Build a consistent routine with manageable workouts, balanced meals, sufficient hydration and recovery. Review your progress weekly and adjust gradually.");card("Important","This starter Android version does not yet include the desktop project's adaptive learning engine or its full recommendation history.");button("BACK",()->dashboard());}
    void msg(String t,String m){new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("OK",null).show();}
}
